-- Global read-only command presets with client-side plan presentation.
create table if not exists public.command_presets (
  id text primary key,
  label text not null,
  text text not null,
  category text not null default 'uncategorized',
  sort_order integer not null default 0,
  required_plan text not null default 'free' check (required_plan in ('free', 'pro')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

alter table public.command_presets enable row level security;

drop policy if exists command_presets_select_authenticated on public.command_presets;
create policy command_presets_select_authenticated
  on public.command_presets for select to authenticated
  using (true);

grant select on public.command_presets to authenticated;
revoke insert, update, delete on public.command_presets from anon, authenticated;

alter table public.user_commands
  add column if not exists preset_id text references public.command_presets(id) on delete set null;

create index if not exists user_commands_preset_id_idx
  on public.user_commands (preset_id);

with seed as (
  select *
  from jsonb_to_recordset($presets$[{"id":"a1b2c3d4-minimal-copy-0001-0000-000000000006","label":"最小化修改","text":"遵循最小化修改原则。","category":"开发指令","sort_order":0,"required_plan":"free"},{"id":"a1b2c3d4-code-review-0001-0000-000000000002","label":"代码审查","text":"对这段代码做深度Code Review：检查可读性、边界情况、安全隐患、性能问题、设计模式合理性，给出具体改进建议。","category":"开发指令","sort_order":1,"required_plan":"free"},{"id":"a1b2c3d4-multi-review-0001-0000-000000000003","label":"多轮审查","text":"从不同角度反复审查：代码质量、架构合理性、边界情况、安全性。发现问题逐项记录并优化。","category":"开发指令","sort_order":2,"required_plan":"pro"},{"id":"a1b2c3d4-deep-fix-0001-0000-000000000001","label":"深研修复","text":"分析这个bug：先复现问题，追踪调用链找到根因，提出3个修复方案并附置信度，等确认后再修复。","category":"开发指令","sort_order":3,"required_plan":"pro"},{"id":"a1b2c3d4-test-coverage-0001-0000-000000000004","label":"测试覆盖","text":"列出当前代码中所有未被测试覆盖的业务行为，用\"should {行为}\"格式输出，按模块分组。","category":"开发指令","sort_order":4,"required_plan":"pro"},{"id":"a1b2c3d4-perf-diag-0001-0000-000000000005","label":"性能诊断","text":"分析当前代码的性能瓶颈，列出最影响性能的问题，给出优化方案和预期提升幅度。","category":"开发指令","sort_order":5,"required_plan":"pro"},{"id":"a1b2c3d4-summarize-0001-0000-000000000007","label":"总结要点","text":"总结刚才讨论的所有关键点，保持简洁但不遗漏重要信息。","category":"开发指令","sort_order":6,"required_plan":"pro"},{"id":"a1b2c3d4-rewrite-0001-0000-000000000008","label":"重写精简","text":"重写这段文字，去除重复和不必要的细节，保持原有逻辑和含义，直接切入要点。","category":"开发指令","sort_order":7,"required_plan":"pro"},{"id":"b1c2d3e4-ui-design-0001-0000-000000000001","label":"UI设计","text":"生成一张高保真UI界面截图。信息层级清晰，留白充足，文字清晰可读无乱码。布局结构合理，组件间距一致，符合平台设计规范。风格统一，配色协调，光影自然。","category":"AI绘图","sort_order":8,"required_plan":"free"},{"id":"b1c2d3e4-social-screenshot-0001-0000-000000000002","label":"社交截图","text":"生成一张高仿社交平台内容截图。包含完整的界面元素：状态栏、账号信息区、正文内容区、互动数据、底部操作栏。比例固定，文字准确可读，禁止乱码和占位文本，界面元素完整真实。","category":"AI绘图","sort_order":9,"required_plan":"pro"},{"id":"b1c2d3e4-infographic-0001-0000-000000000003","label":"信息图","text":"生成一张信息层级清晰的中文信息图。包含标题区和多个内容模块，每个模块有图标、短标题和简要说明。模块间用箭头或颜色区分信息流向。文字短而精炼，整体结构化布局，可读性强，不要大段正文。","category":"AI绘图","sort_order":10,"required_plan":"free"},{"id":"b1c2d3e4-arch-diagram-0001-0000-000000000004","label":"架构图","text":"生成一张结构化技术架构或系统设计图。核心模块用编号面板排列，模块间用箭头和连线表示数据流或调用关系。每个模块包含图标、短标题和关键参数。工程白皮书式信息图风格，低饱和配色，浅色背景，严格结构化布局，不要乱码文字。","category":"AI绘图","sort_order":11,"required_plan":"pro"},{"id":"b1c2d3e4-product-photo-0001-0000-000000000005","label":"产品摄影","text":"生成一张商业级产品展示图。产品居中，材质细节清晰可见，灯光立体感强（柔光+轮廓光）。背景干净不抢主体，整体构图专业，质感超写实。可直接用于电商或宣传用途。","category":"AI绘图","sort_order":12,"required_plan":"pro"},{"id":"b1c2d3e4-brand-design-0001-0000-000000000006","label":"品牌设计","text":"生成一套完整的品牌视觉方案。包含Logo、主辅色系、字体方向，以及名片、App图标、网站首页、社媒模板等多个触点的应用效果。整体风格统一，纯白背景方便抠图，所有物料保持一致的品牌识别感。","category":"AI绘图","sort_order":13,"required_plan":"pro"},{"id":"b1c2d3e4-poster-0001-0000-000000000007","label":"海报设计","text":"设计一张视觉冲击力强的海报。主视觉元素突出，标题文字巨大可读且拼写正确。版式构图有张力，色彩搭配有氛围感。只需要一张完整海报，不要展示板、多方案拼贴或过程稿。输出高分辨率，适合社媒传播。","category":"AI绘图","sort_order":14,"required_plan":"pro"},{"id":"b1c2d3e4-typo-poster-0001-0000-000000000008","label":"字体海报","text":"生成一张高级概念字体海报。标题文字是唯一的主视觉，巨大、可读、有力量感。字体经过定制化设计，字重、间距、变形和负空间表达标题的气质。4-6色调色板，大胆留白，丝网印刷颗粒质感，博物馆级平面设计水准。不要通用字效、3D字体或杂乱拼贴。","category":"AI绘图","sort_order":15,"required_plan":"pro"},{"id":"b1c2d3e4-architecture-0001-0000-000000000009","label":"空间渲染","text":"生成一张超写实建筑空间效果图。人眼视角，广角镜头，透视准确不变形。材质真实，光影层次丰富，室外冷光与室内暖光形成对比。UE5渲染风格，8K画质，光线追踪。空间功能定位清晰，动线合理。","category":"AI绘图","sort_order":16,"required_plan":"pro"},{"id":"b1c2d3e4-product-teardown-0001-0000-000000000010","label":"产品拆解","text":"生成一张概念产品研发拆解板。中心展示最终产品hero render，周围分布：灵感来源分析、形态迭代过程、人体工学验证、内部结构分层拆解、材质方案和关键规格表。工业设计提案板风格，白底，技术图纸与产品摄影混合，细线标注清晰。不只是成品渲染，必须展示完整的研发分析过程。","category":"AI绘图","sort_order":17,"required_plan":"pro"},{"id":"cc-sep-write","label":"── 写作 ──","text":"","category":"CopyClaw","sort_order":18,"required_plan":"pro"},{"id":"cc-writing-001","label":"公众号写作","text":"WeMedia skill：帮我写篇公众号长文。","category":"CopyClaw","sort_order":19,"required_plan":"free"},{"id":"cc-writing-002","label":"选题方向","text":"writi